const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function getInfoAsync(obj) {
    return new Promise((resolve, reject) => {
      obj.getInfo((res, err) => (err ? reject(err) : resolve(res)));
    });
  }

  // 1) Geometry & Time
  const volc = ee.Geometry.Point([130.657, 31.593]); // Sakurajima
  const near = volc.buffer(5000);
  const far = volc.buffer(60000);
  const region = far.difference(near, 1);
  const start = '2015-05-21';
  const end = '2015-05-22';
  const proj = ee.Projection('EPSG:32652'); // UTM zone 52N
  const scale = 1000;

  // Helpers
  function absDeg(a) { return ee.Number(a).abs(); }
  function wrap180(a) { return ee.Number(a).add(180).mod(360).subtract(180); }
  function angToDeg(a) { return ee.Number(a).multiply(180).divide(Math.PI); }

  function brightnessFrom(img) {
    const bands = img.bandNames();
    const hasB03 = bands.contains('sur_refl_b03');
    const b01 = img.select('sur_refl_b01').multiply(0.0001);
    const b02 = img.select('sur_refl_b02').multiply(0.0001);
    const br = ee.Image(ee.Algorithms.If(hasB03,
      b01.add(img.select('sur_refl_b03').multiply(0.0001)).divide(2),
      b01
    )).rename('bright');
    const ndvi = b02.add(b01).neq(0).multiply(b02.subtract(b01).divide(b02.add(b01))).rename('ndvi');
    return br.addBands(ndvi);
  }

  async function pickImage(collectionId, startDate, endDate) {
    let col = ee.ImageCollection(collectionId).filterDate(startDate, endDate).filterBounds(volc);
    const size = await getInfoAsync(col.size());
    return { col, size };
  }

  async function computeOrientation(colId, startDate, endDate, label) {
    // Try GA, fallback to GQ
    let useId = colId;
    let pick = await pickImage(useId, startDate, endDate);
    let source = label + ' GA';
    if (pick.size === 0 && colId.indexOf('MOD09GA') > -1) {
      useId = 'MODIS/006/MOD09GQ';
      pick = await pickImage(useId, startDate, endDate);
      source = label + ' GQ';
    } else if (pick.size === 0 && colId.indexOf('MYD09GA') > -1) {
      useId = 'MODIS/006/MYD09GQ';
      pick = await pickImage(useId, startDate, endDate);
      source = label + ' GQ';
    }
    if (pick.size === 0) {
      // Try +/- 1 day
      const s2 = ee.Date(startDate).advance(-12, 'hour').format('YYYY-MM-dd').getInfo();
      const e2 = ee.Date(endDate).advance(12, 'hour').format('YYYY-MM-dd').getInfo();
      pick = await pickImage(useId, s2, e2);
    }
    const sizeFinal = pick.size;
    if (sizeFinal === 0) {
      return { tag: 'C1', info: { source, images: 0 } };
    }

    // Mosaic and clip
    let img = pick.col.sort('system:time_start').mosaic().clip(region);

    // Brightness & NDVI
    const brNd = brightnessFrom(img);
    const bright = brNd.select('bright');
    const ndvi = brNd.select('ndvi');

    // Monthly background (same product family Terra/Aqua)
    const monthStart = '2015-05-01';
    const monthEnd = '2015-06-01';
    const monthCol = ee.ImageCollection(useId).filterDate(monthStart, monthEnd).filterBounds(volc)
      .map(function(im) { return brightnessFrom(im).select(['bright']); });
    const bg = monthCol.median().select('bright').rename('bg');
    const anomaly = bright.subtract(bg).rename('anom');

    // Detection mask: anomaly > t & NDVI < 0.2 & brightness > 0.03
    const detMask = anomaly.gt(0.015).and(ndvi.lt(0.2)).and(bright.gt(0.03));
    const weight = anomaly.updateMask(detMask);

    // Coordinates in UTM
    const coords = ee.Image.pixelCoordinates(proj).rename(['x', 'y']).reproject({crs: proj, scale: scale});
    const x = coords.select('x');
    const y = coords.select('y');

    // Volcano coords in same CRS
    const volcXY = ee.Image.pixelCoordinates(proj).sample(volc, scale).first();
    const x0 = ee.Number(volcXY.get('x'));
    const y0 = ee.Number(volcXY.get('y'));

    // Reduce for stats
    const wx = x.multiply(weight);
    const wy = y.multiply(weight);
    const ones = ee.Image.constant(1).updateMask(detMask);

    const reducers = ee.Reducer.sum().repeat(3).combine({reducer2: ee.Reducer.count(), sharedInputs: true});
    const stats = ee.Image.cat(weight, wx, wy, ones)
      .reduceRegion({
        reducer: reducers,
        geometry: region,
        scale: scale,
        maxPixels: 1e9,
        crs: proj
      });

    const wSum = ee.Number(stats.get('constant_sum'));
    const xwSum = ee.Number(stats.get('x_sum'));
    const ywSum = ee.Number(stats.get('y_sum'));
    const pixCount = ee.Number(stats.get('constant_count'));

    const wSumVal = await getInfoAsync(wSum);
    const pixCountVal = await getInfoAsync(pixCount);

    // Optional cloud percent for GA using state_1km
    let cloudPct = null;
    if (useId.indexOf('GA') > -1 && img.bandNames().contains('state_1km')) {
      const qa = img.select('state_1km');
      // Cloud state bits 0-1: 00 clear, 01 cloudy, 10 mixed
      const cloudState = qa.bitwiseAnd(3);
      const cirrus = qa.rightShift(10).bitwiseAnd(3); // bits 10-11
      const cloudMaskImg = cloudState.neq(0).or(cirrus.neq(0)).rename('cloud');
      const cStat = cloudMaskImg.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      });
      cloudPct = await getInfoAsync(cStat.get('cloud'));
      if (cloudPct !== null) cloudPct = Math.round(cloudPct * 1000) / 10;
    }

    if (wSumVal === null || pixCountVal === null) {
      return { tag: 'C3', info: { source, images: sizeFinal } };
    }
    if (pixCountVal === 0 || wSumVal === 0) {
      return { tag: 'C2', info: { source, images: sizeFinal, pix: pixCountVal, w: wSumVal } };
    }

    // Weighted centroid
    const cx = xwSum.divide(wSum);
    const cy = ywSum.divide(wSum);
    const dx = cx.subtract(x0);
    const dy = cy.subtract(y0);

    // Angle in degrees from East CCW (-180..180)
    const angle = angToDeg(ee.Number(dy).atan2(dx));
    const angleVal = await getInfoAsync(angle);
    if (angleVal === null || isNaN(angleVal)) {
      return { tag: 'C3', info: { source, images: sizeFinal } };
    }

    // Categorize
    const a = angleVal;
    let dir = 'Other';
    if (a >= -60 && a <= 60) dir = 'E';
    else if (a >= -150 && a <= -30) dir = 'S';

    return {
      tag: 'OK',
      info: {
        source,
        images: sizeFinal,
        pix: pixCountVal,
        w: Math.round(wSumVal * 1e6) / 1e6,
        angle: Math.round(a * 10) / 10,
        dir,
        cloudPct
      }
    };
  }

  try {
    const terra = await computeOrientation('MODIS/006/MOD09GA', start, end, 'Terra');
    const aqua = await computeOrientation('MODIS/006/MYD09GA', start, end, 'Aqua');

    // Handle collection issues
    if (terra.tag === 'C1' || aqua.tag === 'C1') {
      console.log(`Terra Images: ${terra.info?.images ?? 0}`);
      console.log(`Aqua Images: ${aqua.info?.images ?? 0}`);
      console.log('C1');
      return;
    }
    if (terra.tag === 'C2' || aqua.tag === 'C2') {
      console.log(`Terra Images: ${terra.info.images}, PlumePix: ${terra.info.pix}, W:${terra.info.w}`);
      console.log(`Aqua Images: ${aqua.info.images}, PlumePix: ${aqua.info.pix}, W:${aqua.info.w}`);
      console.log('C2');
      return;
    }
    if (terra.tag === 'C3' || aqua.tag === 'C3') {
      console.log('C3');
      return;
    }

    // Print concise evidence
    const t = terra.info;
    const m = aqua.info;
    console.log(`Terra ${t.source}: ${t.images} img, PlumePix: ${t.pix}, W:${t.w}${t.cloudPct!=null?`, Cloud%:${t.cloudPct}`:''}`);
    console.log(`Aqua  ${m.source}: ${m.images} img, PlumePix: ${m.pix}, W:${m.w}${m.cloudPct!=null?`, Cloud%:${m.cloudPct}`:''}`);
    console.log(`Terra Angle: ${t.angle}°, Dir:${t.dir}`);
    console.log(`Aqua  Angle: ${m.angle}°, Dir:${m.dir}`);

    // Decide: "first east then south" vs "first south then east"
    function scoreES(aEarly, aLater) {
      const earlyE = (aEarly >= -60 && aEarly <= 60) ? 1 : 0;
      const laterS = (aLater >= -150 && aLater <= -30) ? 1 : 0;
      // Fallback continuous proximity
      const dE = Math.min(Math.abs(aEarly - 0), Math.abs(aEarly - 360), Math.abs(aEarly + 360));
      const dS = Math.min(Math.abs(aLater + 90), Math.abs(aLater - 270), Math.abs(aLater + 450));
      return earlyE + laterS + (2 - (dE / 90 + dS / 90)); // higher is better
    }
    function scoreSE(aEarly, aLater) {
      const earlyS = (aEarly >= -150 && aEarly <= -30) ? 1 : 0;
      const laterE = (aLater >= -60 && aLater <= 60) ? 1 : 0;
      const dS = Math.min(Math.abs(aEarly + 90), Math.abs(aEarly - 270), Math.abs(aEarly + 450));
      const dE = Math.min(Math.abs(aLater - 0), Math.abs(aLater - 360), Math.abs(aLater + 360));
      return earlyS + laterE + (2 - (dS / 90 + dE / 90));
    }

    const sES = scoreES(t.angle, m.angle);
    const sSE = scoreSE(t.angle, m.angle);
    console.log(`Scores ES:${sES.toFixed(2)} SE:${sSE.toFixed(2)}`);

    const answer = sES >= sSE ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
